local LuaClass = require("Core/LuaClass")
local UIViewModel = require("UI/UIViewModel")
local HouseCommon = require("Game/House/HouseCommon")
local UIBindableList = require("UI/UIBindableList")
local UIBindableBagSlotList = require("Game/NewBag/VM/UIBindableBagSlotList")
local HouseDecorateSlotItemVM = require("Game/House/VM/HouseDecorateSlotItemVM")

local HouseDecoratePanelVM = LuaClass(UIViewModel)

function HouseDecoratePanelVM:Ctor()
    self.CurrentItemVMList = UIBindableBagSlotList.New(HouseDecorateSlotItemVM)
    self.SelIndex = nil
end

function HouseDecoratePanelVM:UpdateItems(Items)
    local DecorateItems = {}
    local Index = 1
    --更新下方ITEM
    for k,v in pairs(Items) do
        table.insert(DecorateItems,{Index = Index,ResID = v.ResID, GID = v.GID})
        Index = Index + 1
    end

    self.CurrentItemVMList:UpdateByValues(DecorateItems)
end

function HouseDecoratePanelVM:GetItem(Index)
    return self.CurrentItemVMList:Get(Index)
end

function HouseDecoratePanelVM:SetCurItemIndex(Index)
    self.SelIndex = Index
end

function HouseDecoratePanelVM:UpdateItem(Item,Index)
    if _G.HousingMgr:IsInDoor() then
        if Index >= 10 then
            Index = Index - 9
        else
            Index = (Index - 1) % 3 + 1
        end
    else
        if Index >= 5 then
            Index = Index - 4
        end
    end

    local SlotItemVM = self:GetItem(Index)

    if SlotItemVM ~= nil then
        SlotItemVM:UpdateVM({Index = SlotItemVM.Index,GID = Item.GID,ResID = Item.ResID})
    end
end

return HouseDecoratePanelVM